INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40343, 0, 0, 0, 0, 0, 0, 0, 0, 'I am happy to see that my messages have been received from Orgrimmar, welcome to Spirit Rise, it is time for you to undergo an age old tradition.', 0),
(40458, 0, 0, 0, 0, 0, 0, 0, 0, 'This... green liquid is what they\'re brewing there? <Overseer opens the flask and takes a sniff.> Och, its quite acidic! This is certainly very concerning, if it the mere smells burns your nose hairs I shudder at the thought what it does to flesh. I will warn the others about this, you\'ve proven yourself to be capable to the brotherhood.', 0),
(40510, 0, 0, 0, 0, 0, 0, 0, 0, 'Wow, this is complicated stuff!$B$B<Masey looks baffled by the sheer complexity of the parts!>$B$BThis was truly a piece of art, no wonder those black dragons were fooled.$B$BI\'m gonna take some time to figure out how this stuff works, thanks again.', 0),
(40664, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'ve done well, your work will certainly go a long way in halting their aggresion and lowering the chances of any potential hostile run-ins. The Wildhammer thank you for the effort.', 0),
(40678, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, I watched you killin\' them from the pier!', 0),
(40788, 0, 0, 0, 0, 0, 0, 0, 0, 'Would you look at that! Pristine too, nice work, excellent work even. My client was going to get a bit tight and upset with me if I didn\'t pull through, so you came in clutch.$B$BHere, as I promised.', 0),
(41778, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, the Libram of Voracity. Have you browsed its pages? For the unkeen eye, it is merely a collection of disconnected images and cryptic words, but for the enlightened, unforeseen potential lies within. The Athenaeum is greatly indebted to your continued assistance.', 0),
(41779, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, the Libram of Constitution. This heavy tome is infamous for harboring difficult incantations and invaluable arcane wisdom some would deem as perilous. The Athenaeum is greatly indebted to your continued assistance.', 0),
(41780, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, the Libram of Resilience. A popular oeuvre among aspiring arcanists. But beware, should you lose yourself within its pages, there is no turning back. The Athenaeum is greatly indebted to your continued assistance.', 0),
(41781, 0, 0, 0, 0, 0, 0, 0, 0, 'The Libram of Rumination. A nefarious grimoire. I\'d best not disclose its contents, and for your sake, I wish you did not open its accursed pages. The Athenaeum is greatly indebted to your continued assistance.', 0),
(41782, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, the Libram of Tenacity. If our statistics are to be trusted, this appears to be the book that has been stolen the most. I wonder why... The Athenaeum is greatly indebted to your continued assistance.', 0),
(41895, 0, 0, 0, 0, 0, 0, 0, 0, 'Why look at this, such potent ichor! This will surely go a long way to making a few coins. Here, take this cut...this cut.', 0),
(60042, 5, 3, 0, 0, 2, 4, 0, 0, 'You did what? All by yourself?$B$BWell, that\'s great news! Hopefully those gnolls won\'t cause us trouble from now on.$B$BHow did you know? Did Terry commission you? No matter, please take this as a reward for your trouble.', 0),
(60112, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $N. It is a shame they never broke free of the Scourge\'s control. They would\'ve made powerful allies.', 0),
(60119, 1, 0, 0, 0, 0, 0, 0, 0, 'Excellent to see you again! My butler observed your actions from a rise in the mountains. Thank you so much for making the roadway safer. One day Wayne Manor will be restored and we can\'t have ogres all over the place!', 0),
(60130, 0, 0, 0, 0, 0, 0, 0, 0, 'Interesting... someone placed a curse upon this ring. I would assume to prevent it from being kept by any would-be thieves. If a murloc had the ring, it would seem that the curse failed to serve its intended purpose.$B$B<Zaldimar utters an incantation while gesturing with his hand. A blinding flash of light explodes from the ring, which appears as a lustrous golden band.>$B$BHere you are.', 0),
(60141, 0, 0, 0, 0, 0, 0, 0, 0, '<You explain why Brother WIlhelm sent you. Eldrin\'s angry, defensive posture softens as you explain, and eventually you see the shine of tears in his eyes.>$B$BMiles away and as busy serving the Light as he is, yet he still finds time to help us. It pains me to burden him so yet again. He\'s already done so much for us, you see.$B$BThings\'ve been hard this year, so I\'ve been goin\' without so Sara and Eric don\'t have to, and... Well, thank you. Bless Brother Wilhelm, and bless you, $N.$B$BHere. I know it\'s not much, but Sara makes them for the locals. Maybe you can find some use in it. Take it! It\'s the least we can do in return for your selfless deed.', 0),
(60150, 0, 0, 0, 0, 0, 0, 0, 0, 'With heroes like you we might even push them out of Mulgore.$B$BTake one, it\'s the least we can do.', 0),
(80369, 1, 0, 0, 0, 0, 0, 0, 0, 'Ah, excellent. Give me but a moment to concoct a brew. Give it a taste.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40343, 0, 0, 'Yes?', 0),
(40458, 0, 0, 'All attempts to sneak in have failed, their hounds can smell everything.', 0),
(40510, 0, 0, 'You found any of them fake whelps?', 0),
(40664, 0, 0, 'Any luck in your hunting $N?', 0),
(40678, 0, 0, 'Have you made the seas safer for me, mon?', 0),
(40788, 0, 0, 'Hey there outrider! You make that trip to Tel\'Abim yet?', 0),
(41778, 0, 0, 'The Athenaeum houses a near endless multitude of tomes and books, filled to the brim with millenia old knowledge. Naturally, this attracts shady individuals intent on pilfering our esteemed collection for their own personal gain. Much to our dismay, this has become a daily occurrence, and my fellow archivists are barely bothered by it. Please, if you find any of our lost librams inside and outside of Dire Maul, return them to me.', 0),
(41779, 0, 0, 'The Athenaeum houses a near endless multitude of tomes and books, filled to the brim with millenia old knowledge. Naturally, this attracts shady individuals intent on pilfering our esteemed collection for their own personal gain. Much to our dismay, this has become a daily occurrence, and my fellow archivists are barely bothered by it. Please, if you find any of our lost librams inside and outside of Dire Maul, return them to me.', 0),
(41780, 0, 0, 'The Athenaeum houses a near endless multitude of tomes and books, filled to the brim with millenia old knowledge. Naturally, this attracts shady individuals intent on pilfering our esteemed collection for their own personal gain. Much to our dismay, this has become a daily occurrence, and my fellow archivists are barely bothered by it. Please, if you find any of our lost librams inside and outside of Dire Maul, return them to me.', 0),
(41781, 0, 0, 'The Athenaeum houses a near endless multitude of tomes and books, filled to the brim with millenia old knowledge. Naturally, this attracts shady individuals intent on pilfering our esteemed collection for their own personal gain. Much to our dismay, this has become a daily occurrence, and my fellow archivists are barely bothered by it. Please, if you find any of our lost librams inside and outside of Dire Maul, return them to me.', 0),
(41782, 0, 0, 'The Athenaeum houses a near endless multitude of tomes and books, filled to the brim with millenia old knowledge. Naturally, this attracts shady individuals intent on pilfering our esteemed collection for their own personal gain. Much to our dismay, this has become a daily occurrence, and my fellow archivists are barely bothered by it. Please, if you find any of our lost librams inside and outside of Dire Maul, return them to me.', 0),
(41895, 0, 0, 'Psst! You got that ichor?...that ichor?', 0),
(60042, 4, 0, 'I hope you have some good news for me, $N!', 0),
(60112, 0, 0, 'They all used to explore Tirisfal together. Karrel was a blacksmith, Daniel was a huntsman and Stephen\'s wisdom guided them all. To see them like this breaks my heart.', 0),
(60119, 0, 6, 'Hello again! I assume since you\'re here the task is complete? No?$B$BA pity.', 0),
(60130, 0, 0, 'Why are you showing me this dirty trinket? Look, there\'s young Mages in need of my attention, so I really don\'t have time for... Oh? A magical enchantment, you say?', 0),
(60141, 0, 0, 'Are you here from Stormwind?$B$BWe told you before, we don\'t have any money left to spare for Lady Prestor\'s coffers! Can\'t you see I have a family to feed?', 0),
(60150, 0, 0, 'Show them that we are not to be meddled with.', 0),
(80369, 1, 1, 'Has your hunt gone well?', 0);
